const ELEMENT_PROP_KEYS = new Set(["theme","word","interval","firstSnap","accent","fontFamily","ink","background","scale","delay","grain","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  word: "Typeset",
  interval: 7,
  firstSnap: 30,
  accent: "#3B5BFD",
  fontFamily: "Fraunces",
  scale: 1,
  delay: 0,
  grain: true,
  speed: 1,
};

type KerningSnapElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof KerningSnapBase>;

const KerningSnapInner = forwardRef<
  HTMLDivElement,
  KerningSnapElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<KerningSnap>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <KerningSnapBase
          {...(componentProps as unknown as ComponentProps<typeof KerningSnapBase>)}
        />
      </div>
    </Sequence>
  );
});

export const KerningSnap = Interactive.withSchema({
  Component: KerningSnapInner,
  componentName: "<KerningSnap>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
